def canon(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), allow_nan=False).encode()


def sha(value):
    return hashlib.sha256(value).hexdigest()


def require(ok, message):
    if not ok:
        raise ValueError(message)


def dt(value):
    result = datetime.fromisoformat(str(value).replace('Z', '+00:00'))
    require(result.tzinfo is not None, 'Explicit timezone required')
    return result.astimezone(UTC)


def stamp(value):
    return value.astimezone(UTC).isoformat().replace('+00:00', 'Z')


def finite(value):
    try:
        result = float(value)
        return result if math.isfinite(result) else None
    except (ValueError, TypeError):
        return None


def progress(**values):
    with LOCK:
        STATE.update(values)


def load_core():
    raw = zlib.decompress(base64.b85decode(CORE_B85))
    require(sha(raw) == CORE_SHA256, 'Pinned core checksum mismatch')
    core = types.ModuleType('pinned_p32_read_only_core')
    exec(compile(raw, '<pinned-p32-read-only-core>', 'exec'), core.__dict__)
    core.progress = progress
    return core


def load_reference(core, check_controls=True):
    raw = zlib.decompress(base64.b85decode(REFERENCE_B85))
    require(sha(raw) == REFERENCE_SHA256, 'Corrected reference checksum mismatch')
    reference = json.loads(raw)
    payload = core.unpack()
    engine = core.engine_for(payload)
    controls = core.baseline_controls(payload, engine) if check_controls else []
    case = next(x for x in payload['reference']['baselines'] if x['name'] == core.PRIMARY)
    expected = payload['reference']['p31_book'] + case['short_book']
    require(core.digest(expected) == reference['book_sha256'], 'Corrected book identity changed')
    book = reference['book']
    require(book == expected and len(book) == 3391 and len({r['sid'] for r in book}) == 32,
            'Expected complete pinned P32 book')
    require(len(reference['geometry']) == len(book), 'Geometry coverage incomplete')
    for i, row in enumerate(book):
        g = reference['geometry'][i]
        require(g['index'] == i and g['sid'] == row['sid'] and g['pair'] == row['pair']
                and g['side'] == row['side'], 'Geometry index/identity mismatch')
        sign = 1 if row['side'] == 'BUY' else -1
        distance = sign * (g['fill'] - g['stop'])
        require(distance > 0 and sign * (g['target'] - g['fill']) > 0,
                'Invalid frozen barriers')
        require(abs(distance - g['stop_distance']) < 1e-9, 'Frozen risk distance changed')
        if row['r'] > 0 and row['pair'] != 'EUR_CHF':
            require(abs(sign * (g['target'] - g['fill']) / distance - row['r']) < 1e-8,
                    'Frozen positive target R mismatch')
    return reference, payload, controls


def configuration(core):
    result = core.config()
    cutoff = dt(os.getenv('P32_ROLLOVER_LIVE_CUTOFF_UTC', stamp(datetime.now(UTC))))
    require(core.LIVE_START < cutoff <= datetime.now(UTC), 'Invalid live cohort cutoff')
    result['cutoff'] = cutoff
    result['workers'] = int(os.getenv('P32_ROLLOVER_WORKERS', '4'))
    result['requests_per_second'] = float(os.getenv('P32_ROLLOVER_REQUESTS_PER_SECOND', '4'))
    require(1 <= result['workers'] <= 4, 'Workers must be between 1 and 4')
    require(0 < result['requests_per_second'] <= 5, 'Request rate must be >0 and <=5')
    return result


class ThrottledReader:
    def __init__(self, core, config, transport=None):
        self.reader = core.Reader(config, transport)
        self.lock = threading.Lock()
        self.next_at = 0.0
        self.spacing = 1 / config.get('requests_per_second', 4)

    @property
    def receipts(self):
        return self.reader.receipts

    def get(self, kind, path, params=None):
        with self.lock:
            now = time.monotonic()
            delay = max(0, self.next_at - now)
            self.next_at = max(now, self.next_at) + self.spacing
        if delay:
            time.sleep(delay)
        return self.reader.get(kind, path, params)


def weekend_closed(t):
    local = t.astimezone(NY)
    return (local.weekday() == 5 or (local.weekday() == 4 and local.hour >= 17)
            or (local.weekday() == 6 and local.hour < 17))


def aligned_floor(t, seconds):
    return datetime.fromtimestamp(math.floor(t.timestamp() / seconds) * seconds, UTC)


def coverage(candles, start, end, seconds):
    times = {dt(c['time']) for c in candles}
    first = aligned_floor(start, seconds)
    if first < start:
        first += timedelta(seconds=seconds)
    result = dict(expected_slots=0, observed_slots=0, missing_weekend_slots=0,
                  missing_unexplained_slots=0, first_unexplained_gap_utc=None)
    t = first
    while t + timedelta(seconds=seconds) <= end:
        result['expected_slots'] += 1
        if t in times:
            result['observed_slots'] += 1
        elif weekend_closed(t):
            result['missing_weekend_slots'] += 1
        else:
            result['missing_unexplained_slots'] += 1
            if result['first_unexplained_gap_utc'] is None:
                result['first_unexplained_gap_utc'] = stamp(t)
        t += timedelta(seconds=seconds)
    return result


class CandleStore:
    """Content-verified, persistent, broker-specific candle cache. Never caches tokens."""
    def __init__(self, reader, config, directory):
        self.reader, self.config = reader, config
        self.db = sqlite3.connect(str(directory / 'candle_cache.sqlite3'), check_same_thread=False)
        self.db.execute('PRAGMA journal_mode=WAL')
        self.db.execute('CREATE TABLE IF NOT EXISTS candles '
                        '(key TEXT PRIMARY KEY, identity TEXT, body BLOB, sha256 TEXT)')
        self.db.commit()
        self.lock = threading.RLock()
        self.key_locks = {}
        self.used = set()
        self.hits = 0
        self.downloads = 0

    def identity(self, pair, gran, start, end):
        return dict(schema='MBA_UNSMOOTHED_V1', broker=self.config['broker'], pair=pair,
                    granularity=gran, start=stamp(start), end=stamp(end), price='MBA',
                    smooth=False, includeFirst=True)

    def validate(self, obj, ident):
        require(obj.get('instrument') == ident['pair'] and obj.get('granularity') == ident['granularity'],
                'Native candle instrument/granularity mismatch')
        require(isinstance(obj.get('candles'), list), 'Missing candle array')
        start, end = dt(ident['start']), dt(ident['end'])
        seconds = STEP[ident['granularity']]
        rows = []
        previous = None
        for candle in obj['candles']:
            t = dt(candle['time'])
            require(previous is None or t > previous, 'Candle times duplicated or not increasing')
            previous = t
            require(start <= t < end, 'Candle lies outside requested interval')
            require(t == aligned_floor(t, seconds), 'Candle is not aligned to native granularity')
            if candle.get('complete') is not True or t + timedelta(seconds=seconds) > end:
                continue
            row = {'time': stamp(t), 'complete': True, 'volume': candle.get('volume')}
            for side in ('mid', 'bid', 'ask'):
                prices = candle.get(side)
                require(isinstance(prices, dict), 'Requested MBA component missing: ' + side)
                values = {k: finite(prices.get(k)) for k in 'ohlc'}
                require(all(v is not None and v > 0 for v in values.values()), 'Invalid native price')
                require(values['l'] <= min(values['o'], values['c']) <= max(values['o'], values['c']) <= values['h'],
                        'Invalid native OHLC')
                row[side] = values
            require(row['ask']['o'] >= row['bid']['o'] - 1e-10
                    and row['ask']['c'] >= row['bid']['c'] - 1e-10, 'Negative boundary spread')
            rows.append(row)
        return dict(instrument=ident['pair'], granularity=ident['granularity'], candles=rows)

    def block(self, pair, gran, start, end):
        ident = self.identity(pair, gran, start, end)
        key = sha(canon(ident))
        with self.lock:
            key_lock = self.key_locks.setdefault(key, threading.Lock())
        with key_lock:
            with self.lock:
                existing = self.db.execute('SELECT identity,body,sha256 FROM candles WHERE key=?', (key,)).fetchone()
            if existing:
                raw = zlib.decompress(existing[1])
                require(existing[0] == canon(ident).decode() and sha(raw) == existing[2], 'Candle cache checksum/identity mismatch')
                normalized = self.validate(json.loads(raw), ident)
                with self.lock:
                    self.hits += 1
                    self.used.add(key)
                return normalized['candles']
            obj = self.reader.get('broker', '/v3/instruments/' + pair + '/candles',
                                  {'from': ident['start'], 'to': ident['end'], 'granularity': gran,
                                   'price': 'MBA', 'smooth': 'false', 'includeFirst': 'true'})
            normalized = self.validate(obj, ident)
            raw = canon(normalized)
            with self.lock:
                self.db.execute('INSERT OR REPLACE INTO candles VALUES (?,?,?,?)',
                                (key, canon(ident).decode(), zlib.compress(raw, 6), sha(raw)))
                self.db.commit()
                self.downloads += 1
                self.used.add(key)
            return normalized['candles']

    def range(self, pair, gran, start, end):
        require(pair in ('AUD_JPY', 'AUD_USD', 'EUR_CHF', 'EUR_GBP', 'EUR_JPY', 'EUR_USD', 'GBP_USD', 'USD_CAD', 'USD_JPY'), 'Unapproved candle pair')
        require(gran in STEP and start <= end, 'Invalid candle range')
        require(start == aligned_floor(start, STEP[gran]) and end == aligned_floor(end, STEP[gran]),
                'Range endpoints must be aligned')
        rows = []
        # Maximum possible bars is 4800, below OANDA's 5000 limit. No count with from/to.
        while start < end:
            next_end = min(end, start + timedelta(seconds=4800 * STEP[gran]))
            rows.extend(self.block(pair, gran, start, next_end))
            start = next_end
        require(all(dt(rows[i]['time']) < dt(rows[i + 1]['time']) for i in range(len(rows) - 1)),
                'Duplicate/unsorted chunk boundary')
        return rows

    def export(self, archive):
        index = []
        with self.lock:
            keys = sorted(self.used)
        for key in keys:
            with self.lock:
                ident, compressed, checksum = self.db.execute('SELECT identity,body,sha256 FROM candles WHERE key=?', (key,)).fetchone()
            raw = zlib.decompress(compressed)
            require(sha(raw) == checksum, 'Source cache changed before export')
            filename = 'source_candles/' + key + '.json'
            archive.writestr(filename, raw)
            index.append(dict(json.loads(ident), file=filename, sha256=checksum))
        archive.writestr('source_candle_index.json', json.dumps(index, indent=2, sort_keys=True))

    def close(self):
        self.db.close()


def barrier(candle, component, side, fill, stop, target):
    """Only infer order when the known opening price or distinct candles determine it."""
    p = candle[component]
    sign = 1 if side == 'BUY' else -1
    stop_open = sign * (p['o'] - stop) <= 1e-12
    target_open = sign * (p['o'] - target) >= -1e-12
    stop_hit = p['l'] <= stop + 1e-12 if sign == 1 else p['h'] >= stop - 1e-12
    target_hit = p['h'] >= target - 1e-12 if sign == 1 else p['l'] <= target + 1e-12
    if stop_open:
        kind, price = 'STOP', p['o']
    elif target_open:
        kind, price = 'TARGET', target
    elif stop_hit and target_hit:
        return dict(kind='AMBIGUOUS_BOTH', modeled_exit_price=None, modeled_price_r=None,
                    open_gap=False, stop_touched=True, target_touched=True)
    elif stop_hit:
        kind, price = 'STOP', stop
    elif target_hit:
        kind, price = 'TARGET', target
    else:
        return None
    return dict(kind=kind, modeled_exit_price=price,
                modeled_price_r=sign * (price - fill) / abs(fill - stop),
                open_gap=stop_open or target_open, stop_touched=stop_hit, target_touched=target_hit)


def near_rollover(t):
    local = t.astimezone(NY)
    boundary = local.replace(hour=17, minute=0, second=0, microsecond=0)
    return abs((local - boundary).total_seconds()) <= 1800


def aggregation_check(parent, children, expected_count, pair):
    """Crosscheck already fetched tiers; never replace absent observations."""
    if len(children) != expected_count:
        return dict(status='INCOMPLETE_TIER_COVERAGE', max_error_ticks=None)
    unit = .001 if pair.endswith('_JPY') else .00001
    errors = []
    for component in ('mid', 'bid', 'ask'):
        aggregate = dict(o=children[0][component]['o'], c=children[-1][component]['c'],
                         h=max(c[component]['h'] for c in children), l=min(c[component]['l'] for c in children))
        errors.extend(abs(aggregate[k] - parent[component][k]) / unit for k in 'ohlc')
    maximum = max(errors)
    return dict(status='MATCH_WITHIN_ONE_TICK' if maximum <= 1 + 1e-7 else 'SOURCE_TIER_MISMATCH', max_error_ticks=maximum)


def first_touch(store, record, geometry, native, component):
    step = STEP[record['tf']]
    entry, end = dt(record['entry']), dt(record['exit'])
    cov = coverage(native, entry, end, step)
    result = dict(component=component, side=record['side'], kind='NO_TOUCH_BY_ARCHIVED_EXIT',
                  interval_start_utc=None, interval_end_utc=None, native_interval_start_utc=None,
                  native_interval_end_utc=None, resolution=None, certainty='NO_TOUCH_OBSERVED',
                  modeled_exit_price=None, modeled_price_r=None, open_gap=False,
                  executable_stop_without_mid_stop_in_same_bar=None, **cov)
    for candle in native:
        touched = barrier(candle, component, record['side'], geometry['fill'], geometry['stop'], geometry['target'])
        if touched is None:
            continue
        begin = dt(candle['time'])
        finish = begin + timedelta(seconds=step)
        result.update(native_interval_start_utc=stamp(begin), native_interval_end_utc=stamp(finish))
        minutes = store.range(record['pair'], 'M1', begin, finish)
        refined_cov = coverage(minutes, begin, finish, 60)
        coarse_check = aggregation_check(candle, minutes, step // 60, record['pair'])
        result.update(native_vs_m1_crosscheck=coarse_check['status'], native_vs_m1_max_error_ticks=coarse_check['max_error_ticks'])
        finer = None
        for minute in minutes:
            hit = barrier(minute, component, record['side'], geometry['fill'], geometry['stop'], geometry['target'])
            if hit is None:
                continue
            fine_begin = dt(minute['time'])
            fine_end = fine_begin + timedelta(minutes=1)
            resolution, chosen, chosen_hit = 'M1', minute, hit
            five_cov = None
            if hit['kind'] == 'AMBIGUOUS_BOTH' or near_rollover(fine_begin):
                fives = store.range(record['pair'], 'S5', fine_begin, fine_end)
                five_cov = coverage(fives, fine_begin, fine_end, 5)
                five_check = aggregation_check(minute, fives, 12, record['pair'])
                result.update(m1_vs_s5_crosscheck=five_check['status'], m1_vs_s5_max_error_ticks=five_check['max_error_ticks'])
                five_hit = next(((c, barrier(c, component, record['side'], geometry['fill'], geometry['stop'], geometry['target']))
                                 for c in fives if barrier(c, component, record['side'], geometry['fill'], geometry['stop'], geometry['target']) is not None), None)
                if five_hit:
                    chosen, chosen_hit = five_hit
                    fine_begin = dt(chosen['time'])
                    fine_end = fine_begin + timedelta(seconds=5)
                    resolution = 'S5'
                else:
                    resolution = 'M1_S5_UNCONFIRMED'
            finer = dict(chosen_hit, interval_start_utc=stamp(fine_begin), interval_end_utc=stamp(fine_end), resolution=resolution)
            # Compare only the same candle's MID high/low, never different side extrema as a spread.
            if component != 'mid' and chosen_hit['kind'] == 'STOP':
                midpoint_crosses_stop = chosen['mid']['l'] <= geometry['stop'] + 1e-12 if record['side'] == 'BUY' else chosen['mid']['h'] >= geometry['stop'] - 1e-12
                finer['executable_stop_without_mid_stop_in_same_bar'] = not midpoint_crosses_stop
            if five_cov is not None:
                finer['s5_unexplained_slots'] = five_cov['missing_unexplained_slots']
                finer['s5_earlier_unexplained_gap'] = (five_cov['first_unexplained_gap_utc'] is not None
                                                     and dt(five_cov['first_unexplained_gap_utc']) < fine_end)
            break
        if finer is None:
            result.update(touched, interval_start_utc=stamp(begin), interval_end_utc=stamp(finish),
                          resolution=record['tf'], certainty='UNCONFIRMED_M1_REFINEMENT')
        else:
            result.update(finer)
            earliest_gap = cov['first_unexplained_gap_utc']
            earlier_gap = earliest_gap is not None and dt(earliest_gap) < dt(result['interval_end_utc'])
            m1_gap = refined_cov['first_unexplained_gap_utc']
            earlier_m1_gap = m1_gap is not None and dt(m1_gap) < dt(result['interval_end_utc'])
            # A gap after the observed first hit does not invalidate that first hit.
            if coarse_check['status'] == 'SOURCE_TIER_MISMATCH' or result.get('m1_vs_s5_crosscheck') == 'SOURCE_TIER_MISMATCH':
                result['certainty'] = 'SOURCE_TIER_MISMATCH'
            elif result.get('s5_earlier_unexplained_gap', False) or result['resolution'] == 'M1_S5_UNCONFIRMED':
                result['certainty'] = 'UNCONFIRMED_S5_REFINEMENT'
            elif earlier_gap or earlier_m1_gap:
                result['certainty'] = 'TOUCH_WITH_EARLIER_UNEXPLAINED_GAP'
            elif result['kind'] == 'AMBIGUOUS_BOTH':
                result['certainty'] = 'AMBIGUOUS_INTRABAR_ORDER'
            else:
                result['certainty'] = 'RESOLVED_TO_CANDLE_INTERVAL'
        return result
    if cov['missing_unexplained_slots']:
        result['certainty'] = 'NO_TOUCH_WITH_UNEXPLAINED_GAPS'
    return result


def archive_comparison(record, touch):
    expected_kind = 'TARGET' if record['r'] > 0 else 'STOP' if record['r'] < 0 else 'FLAT'
    outcome_match = touch['kind'] == expected_kind
    time_match = touch['native_interval_end_utc'] == record['exit']
    resolved = touch['certainty'] == 'RESOLVED_TO_CANDLE_INTERVAL'
    if not resolved:
        status = 'UNRESOLVED_' + touch['certainty']
    elif outcome_match and time_match:
        status = 'EXIT_KIND_AND_NATIVE_INTERVAL_MATCH'
    else:
        status = 'ARCHIVED_PATH_MISMATCH'
    return dict(expected_kind=expected_kind, archived_exit_utc=record['exit'],
                archived_r=record['r'], outcome_match=outcome_match,
                native_exit_interval_match=time_match, status=status,
                modeled_r_minus_archived_r=(touch['modeled_price_r'] - record['r']) if touch['modeled_price_r'] is not None else None)


def historical_trade(store, index, record, geometry):
    entry, end = dt(record['entry']), dt(record['exit'])
    candles = store.range(record['pair'], record['tf'], entry, end)
    mid = first_touch(store, record, geometry, candles, 'mid')
    component = 'bid' if record['side'] == 'BUY' else 'ask'
    executable = first_touch(store, record, geometry, candles, component)
    first = next((c for c in candles if dt(c['time']) == entry), None)
    sign = 1 if record['side'] == 'BUY' else -1
    proxy = first['ask' if sign == 1 else 'bid']['o'] if first else None
    deviation = sign * (proxy - geometry['reference_entry']) / (0.001 if record['pair'].endswith('_JPY') else 0.00001) if proxy is not None else None
    valid_proxy = proxy is not None and sign * (proxy - geometry['stop']) > 0 and sign * (geometry['target'] - proxy) > 0
    proxy_status = 'MISSING_EXACT_ENTRY_BAR' if proxy is None else 'INVALID_PROXY_GEOMETRY' if not valid_proxy else 'WOULD_FAIL_10T_PROXY_GUARD' if deviation > 10 + 1e-7 else 'WITHIN_10T_PROXY_GUARD'
    comparison = archive_comparison(record, mid)
    base = dict(index=index, **record, holding_hours=(end - entry).total_seconds() / 3600,
                geometry_source=geometry['geometry_source'], geometry_validation=geometry['geometry_validation'],
                frozen_fill=geometry['fill'], stop=geometry['stop'], target=geometry['target'],
                stop_distance_pips=geometry['stop_distance'] / (0.01 if record['pair'].endswith('_JPY') else 0.0001),
                next_native_entry_price_proxy=proxy, proxy_adverse_ticks=deviation,
                entry_proxy_status=proxy_status,
                proxy_effective_target_r=sign * (geometry['target'] - proxy) / abs(proxy - geometry['stop']) if valid_proxy else None,
                archived_path_status=comparison['status'])
    for prefix, touch in (('mid', mid), ('executable', executable)):
        base.update({prefix + '_' + k: v for k, v in touch.items()})
    base.update({'archive_' + k: v for k, v in comparison.items()})
    trace = dict(index=index, record=record, geometry=geometry, mid_first_touch=mid,
                 executable_exit_first_touch=executable, archive_comparison=comparison)
    return base, trace


def flatten_candles(candles):
    return [dict(time=c['time'], volume=c['volume'], **{side + '_' + k: c[side][k]
                 for side in ('mid', 'bid', 'ask') for k in 'ohlc'}) for c in candles]


def spread_stats(candles, distance, pip_size):
    values = [max(0, c['ask'][k] - c['bid'][k]) for c in candles for k in ('o', 'c')]
    pips = [x / pip_size for x in values]
    ordered = sorted(pips)
    percentile = None
    if ordered:
        pos = (len(ordered) - 1) * .95
        lo, hi = math.floor(pos), math.ceil(pos)
        percentile = ordered[lo] + (ordered[hi] - ordered[lo]) * (pos - lo)
    return dict(candles=len(candles), boundary_proxy_observations=len(values),
                mean_spread_pips=statistics.fmean(pips) if pips else None,
                median_spread_pips=statistics.median(pips) if pips else None,
                p95_spread_pips=percentile, max_spread_pips=max(pips) if pips else None,
                max_spread_pct_initial_stop=100 * max(values) / distance if values else None)


def boundary_position_state(touch, boundary):
    if not touch:
        return 'NO_PATH_EVIDENCE'
    if touch.get('interval_end_utc') and dt(touch['interval_end_utc']) <= boundary:
        return 'EARLIER_TOUCH' if touch.get('certainty') == 'RESOLVED_TO_CANDLE_INTERVAL' else 'POSSIBLE_EARLIER_TOUCH'
    if touch.get('interval_start_utc') and dt(touch['interval_start_utc']) >= boundary:
        if touch.get('certainty') == 'RESOLVED_TO_CANDLE_INTERVAL':
            return 'NO_PRIOR_TOUCH_OBSERVED'
    return 'TIMING_OR_PATH_UNRESOLVED'


def rollover_event(store, job, schedule):
    record, geometry, boundary = job['record'], job['geometry'], job['boundary']
    entry, end = dt(record['entry']), dt(record['exit'])
    base = dict(cohort=job['cohort'], trade_key=job['trade_key'], pair=record['pair'],
                sid=record['sid'], side=record['side'], entry=record['entry'], exit=record['exit'],
                rollover_utc=stamp(boundary), rollover_new_york=boundary.astimezone(NY).isoformat(),
                original_nominal_exposure=entry < boundary < end,
                entry_or_exit_boundary=edge if (edge := entry == boundary or end == boundary) else False,
                scheduled_charge_days_sensitivity=schedule['days'][boundary.astimezone(NY).strftime('%A').upper()],
                current_rate_sensitivity=schedule['long_rate' if record['side'] == 'BUY' else 'short_rate'],
                schedule_source=schedule['schedule_source'], spread_source='MBA_BOUNDARY_PROXY',
                historical_actual_financing_rate_known=False if job['cohort'] == 'HISTORICAL' else None,
                mid_path_occupancy=boundary_position_state(job.get('mid_touch'), boundary),
                executable_path_occupancy=boundary_position_state(job.get('executable_touch'), boundary),
                observed_daily_financing_cash=job.get('funding_cash'), observed_daily_financing_r=job.get('funding_r'))
    rate = base['current_rate_sensitivity']
    days = base['scheduled_charge_days_sensitivity']
    base['estimated_current_rate_funding_r'] = geometry['fill'] / geometry['stop_distance'] * rate * days / 365 if rate is not None and base['original_nominal_exposure'] else None
    if boundary.astimezone(NY).weekday() == 5:
        base.update(status='CONVENTIONAL_SATURDAY_CLOSURE', rollover_candles=0, control_candles=0)
        return base
    start, planned_finish = boundary - timedelta(minutes=120), boundary + timedelta(minutes=30)
    finish = min(planned_finish, aligned_floor(dt(job['source_cutoff_utc']), 60)) if job.get('source_cutoff_utc') else planned_finish
    require(finish >= start, 'Live cutoff precedes rollover source window')
    base.update(source_window_end_utc=stamp(finish), planned_window_end_utc=stamp(planned_finish),
                window_truncated_at_live_cutoff=finish < planned_finish)
    candles = store.range(record['pair'], 'M1', start, finish)
    roll = [c for c in candles if boundary - timedelta(minutes=30) <= dt(c['time']) < finish]
    control = [c for c in candles if start <= dt(c['time']) < boundary - timedelta(minutes=60)]
    intrade = [c for c in roll if entry <= dt(c['time']) and dt(c['time']) + timedelta(minutes=1) <= end]
    pip_size = .01 if record['pair'].endswith('_JPY') else .0001
    for prefix, subset in (('rollover', roll), ('control', control), ('intrade_rollover', intrade)):
        base.update({prefix + '_' + k: v for k, v in spread_stats(subset, geometry['stop_distance'], pip_size).items()})
    cov = coverage(candles, start, finish, 60)
    base.update(cov)
    side = 'bid' if record['side'] == 'BUY' else 'ask'
    exec_only = []
    for candle in intrade:
        hit = barrier(candle, side, record['side'], geometry['fill'], geometry['stop'], geometry['target'])
        if hit and hit['kind'] == 'STOP':
            mid_stop = candle['mid']['l'] <= geometry['stop'] if record['side'] == 'BUY' else candle['mid']['h'] >= geometry['stop']
            if not mid_stop:
                exec_only.append(candle['time'])
    base.update(executable_stop_without_mid_stop_m1_count=len(exec_only),
                first_executable_stop_without_mid_stop_m1=exec_only[0] if exec_only else None,
                status='WINDOW_WITH_UNEXPLAINED_GAPS' if cov['missing_unexplained_slots'] else 'WINDOW_OBSERVED',
                rollover_to_control_median_spread_ratio=(base['rollover_median_spread_pips'] / base['control_median_spread_pips'])
                if base.get('control_median_spread_pips') else None)
    return base


def live_records(evidence, measured_rows, cutoff):
    """Broker opening timestamps and observed fills take priority over signal timestamps."""
    costs = {r['trade_id']: r for r in measured_rows}
    outcomes = {str(r['oanda_trade_id']): r for r in evidence.get('trades', {}).get('trades', [])}
    openings = {str(t['tradeOpened']['tradeID']): t for t in evidence.get('transactions', [])
                if t.get('type') == 'ORDER_FILL' and t.get('tradeOpened')}
    result = []
    for signal in evidence.get('signals', {}).get('signals', []):
        key = str(signal.get('oanda_trade_id'))
        if signal.get('actual_fill') is None or not signal.get('oanda_trade_id'):
            continue
        opened = openings.get(key)
        if not opened or dt(opened['time']) > cutoff:
            continue
        outcome = outcomes.get(key)
        closed = outcome and outcome.get('fully_closed') and dt(outcome['close_time']) <= cutoff
        end = dt(outcome['close_time']) if closed else cutoff
        fill, stop, target = (float(signal[k]) for k in ('actual_fill', 'stop', 'target'))
        record = dict(entry=stamp(dt(opened['time'])), exit=stamp(end), pair=signal['pair'],
                      sid=signal['strategy_id'], side=signal['side'], tf=signal['timeframe'],
                      actual_closed=bool(closed), signal_id=signal['signal_id'])
        geometry = dict(fill=fill, stop=stop, target=target, stop_distance=abs(fill - stop))
        result.append(dict(trade_key=key, record=record, geometry=geometry, cost_record=costs.get(key)))
    return result


def broker_close_quotes(evidence, signals):
    lookup = {str(s.get('oanda_trade_id')): s for s in signals if s.get('actual_fill') is not None and s.get('oanda_trade_id')}
    rows = []
    for transaction in evidence.get('transactions', []):
        if transaction.get('type') != 'ORDER_FILL':
            continue
        price = transaction.get('fullPrice') or {}
        bid = finite((price.get('bids') or [{}])[0].get('price'))
        ask = finite((price.get('asks') or [{}])[0].get('price'))
        for item in (transaction.get('tradesClosed') or []) + ([transaction['tradeReduced']] if transaction.get('tradeReduced') else []):
            key = str(item.get('tradeID'))
            signal = lookup.get(key)
            if signal is None:
                continue
            side, stop = signal['side'], float(signal['stop'])
            midpoint = (ask + bid) / 2 if ask is not None and bid is not None else None
            executable = bid if side == 'BUY' else ask
            exec_stop = (executable <= stop if side == 'BUY' else executable >= stop) if executable is not None else None
            mid_stop = (midpoint <= stop if side == 'BUY' else midpoint >= stop) if midpoint is not None else None
            distance = abs(float(signal['actual_fill']) - stop)
            rows.append(dict(trade_id=key, close_transaction_id=transaction['id'], time=transaction['time'],
                             pair=signal['pair'], side=side, reason=transaction.get('reason'),
                             actual_fill=signal['actual_fill'], stop=stop, target=signal['target'],
                             observed_best_bid=bid, observed_best_ask=ask, observed_quote_midpoint=midpoint,
                             executable_side='BID' if side == 'BUY' else 'ASK',
                             executable_quote_crosses_stop=exec_stop, quote_midpoint_crosses_stop=mid_stop,
                             executable_stop_without_quote_midpoint_stop=exec_stop and not mid_stop if exec_stop is not None and mid_stop is not None else None,
                             observed_spread_pips=(ask - bid) / (.01 if signal['pair'].endswith('_JPY') else .0001) if midpoint is not None else None,
                             observed_spread_pct_initial_stop=100 * (ask - bid) / distance if midpoint is not None else None,
                             close_financing_cash=finite(item.get('financing')),
                             actual_pl_already_includes_execution_costs=True))
    return rows


def watcher_health(evidence, cutoff):
    rows = []
    for endpoint, expected in (('/live-status', 17), ('/m15-live-status', 8)):
        obj = evidence.get(endpoint)
        if not obj:
            rows.append(dict(endpoint=endpoint, status='NOT_CONFIGURED_OR_MISSING'))
            continue
        cycle = obj.get('last_watcher_cycle')
        if not cycle:
            rows.append(dict(endpoint=endpoint, status='NO_COMPLETED_CYCLE_SNAPSHOT', expected_evaluations=expected))
            continue
        close = dt(cycle['expected_close_utc'])
        age = (cutoff - close).total_seconds()
        complete = cycle.get('all_evaluations_completed') is True and cycle.get('completed_evaluations') == expected and cycle.get('required_evaluations') == expected and not cycle.get('outstanding')
        rows.append(dict(endpoint=endpoint, status='COMPLETE_OBSERVED_CYCLE' if complete else 'INCOMPLETE_OR_DIFFERENT_CYCLE',
                         expected_evaluations=expected, required_evaluations=cycle.get('required_evaluations'),
                         completed_evaluations=cycle.get('completed_evaluations'), expected_close_utc=cycle['expected_close_utc'],
                         snapshot_age_vs_cohort_cutoff_seconds=age, outstanding=cycle.get('outstanding'),
                         fresh_within_one_cycle_plus_120s=0 <= age <= (3600 if expected == 17 else 900) + 120,
                         source_is_collection_time_snapshot=True))
    return rows


class ReportFiles:
    def __init__(self, directory):
        self.directory = directory / 'reports'
        self.directory.mkdir(parents=True, exist_ok=True)
        self.members = set()

    def text(self, name, value):
        path = self.directory / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(value, encoding='utf-8')
        self.members.add(name)

    def json(self, name, value):
        self.text(name, json.dumps(value, indent=2, sort_keys=True, allow_nan=False))

    def csv(self, name, rows):
        fields = list(dict.fromkeys(k for row in rows for k in row)) or ['empty']
        path = self.directory / name
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open('w', encoding='utf-8', newline='') as file:
            writer = csv.DictWriter(file, fieldnames=fields)
            writer.writeheader()
            for row in rows:
                writer.writerow({k: json.dumps(v, sort_keys=True) if isinstance(v, (dict, list, tuple)) else v for k, v in row.items()})
        self.members.add(name)

    def save(self, directory, store=None):
        temporary = directory / (RESULT_NAME + '.tmp')
        checksums = {}
        with zipfile.ZipFile(temporary, 'w', zipfile.ZIP_DEFLATED, compresslevel=6) as archive:
            for name in sorted(self.members):
                path = self.directory / name
                checksums[name] = dict(bytes=path.stat().st_size, sha256=sha(path.read_bytes()))
                archive.write(path, name)
            archive.writestr('file_manifest.json', json.dumps(checksums, indent=2, sort_keys=True))
            if store:
                store.export(archive)
        temporary.replace(directory / RESULT_NAME)


def output_dir():
    return Path(os.getenv('P32_ROLLOVER_OUTPUT_DIR', str(Path(tempfile.gettempdir()) / 'p32_rollover_path_audit'))).resolve()


def grouped_summary(rows):
    grouped = defaultdict(list)
    for row in rows:
        grouped[(row['cohort'], row['pair'], row['side'])].append(row)
    result = []
    for key, group in sorted(grouped.items()):
        observed = [r for r in group if r.get('rollover_boundary_proxy_observations', 0)]
        values = [r['rollover_max_spread_pct_initial_stop'] for r in observed]
        result.append(dict(cohort=key[0], pair=key[1], side=key[2], boundaries=len(group),
                           distinct_trades=len({r['trade_key'] for r in group}), observed_boundary_windows=len(observed),
                           error_windows=sum(r.get('status') == 'SOURCE_ERROR' for r in group),
                           conventional_saturday_closures=sum(r.get('status') == 'CONVENTIONAL_SATURDAY_CLOSURE' for r in group),
                           unexplained_gap_windows=sum(r.get('missing_unexplained_slots', 0) > 0 for r in group),
                           mean_window_max_spread_pct_stop=statistics.fmean(values) if values else None,
                           worst_window_max_spread_pct_stop=max(values) if values else None,
                           executable_only_stop_m1_windows=sum(r.get('executable_stop_without_mid_stop_m1_count', 0) > 0 for r in group),
                           earlier_executable_touch_boundaries=sum(r.get('executable_path_occupancy') == 'EARLIER_TOUCH' for r in group),
                           note='Exposure-window descriptions; repeated long trades are not independent observations'))
    return result


def review_text(summary):
    return '\n'.join([
        '# P32 rollover and long-hold investigation', '',
        f"Status: {summary['status']}. Read-only; orders sent: false.", '',
        f"Six baseline controls passed. Historical paths attempted: {summary['historical_paths_attempted']}/3391.",
        f"MID exit kind/native interval matches: {summary['historical_mid_matches']}; mismatches: {summary['historical_mid_mismatches']}; unresolved/errors: {summary['historical_mid_unresolved']}.",
        f"Rollover boundary jobs: {summary['rollover_boundaries_attempted']}; source errors: {summary['rollover_source_errors']}.", '',
        'Start with historical_path_summary.csv, long_hold_path_review.csv and live_broker_close_quotes.csv. '
        'The MID comparison checks the original frozen archive. The executable comparison uses the same frozen modeled entry and correct exit side; it is a fixed-admission sensitivity.', '',
        'rollover_event_windows.csv compares each rollover window with its paired earlier control. '
        'Do not treat ask-high minus bid-low as a spread. The reported OPEN/CLOSE spreads are candle-boundary proxies; actual broker fullPrice records have stronger provenance.', '',
        'source_candle_index.json links every consumed source block to its identity and checksum. '
        'source_candles/ contains the native evidence. Detailed traces and native long-hold paths are included.', '',
        'Actual net returns already include execution and financing costs. Current-rate historical funding values are sensitivities, not recovered historical charges. '
        'No counterfactual financing is added to actual returns.', '',
        'A path mismatch is a finding requiring investigation. Missing/ambiguous data remain unresolved. '
        'Original archive occupancy may persist after a newly observed earlier barrier; the occupancy columns identify that distinction. '
        'This runner does not validate new management rules or recover 27 missing raw qualification streams.', '',
        'Operational snapshots: watcher_health.csv. A completed cycle is evidence about its recorded candle; it is not a full missed-signal audit.', '',
        '## Limitations', '', *['- ' + s for s in summary['limitations']], '',
    ])


def run_audit(config=None, reader=None, directory=None, reference_override=None):
    directory = Path(directory or output_dir())
    directory.mkdir(parents=True, exist_ok=True)
    reports = ReportFiles(directory)
    store = None
    core = load_core()
    limits = []
    try:
        progress(status='RUNNING', phase='PINNED_BASELINE_CONTROLS', started_at_utc=stamp(datetime.now(UTC)))
        reference, payload, controls = load_reference(core)
        reports.json('protocol.json', PROTOCOL)
        reports.json('baseline_controls.json', controls)
        reports.json('reference_provenance.json', dict(core_sha256=CORE_SHA256, embedded_reference_sha256=REFERENCE_SHA256,
                                                     corrected_archive_sha256=reference['corrected_archive_sha256'],
                                                     correction=reference['correction'], frozen_book_sha256=reference['book_sha256']))
        reports.csv('frozen_p32_book.csv', reference['book'])
        reports.csv('frozen_geometry.csv', reference['geometry'])
        if config is None:
            config = configuration(core)
        if reader is None:
            reader = ThrottledReader(core, config)
        progress(phase='LIVE_READ_ONLY_EVIDENCE')
        evidence, registry, live_limits = core.fetch_live(reader, config, payload)
        limits.extend(live_limits)
        reports.json('live_registry_control.json', registry)
        reports.json('live_evidence.json', core.redact(evidence, config))
        schedules = core.schedules(evidence)
        reports.json('current_funding_schedules.json', schedules)
        actual, financing, actual_summary, signals = core.measured_live(evidence, config['cutoff'])
        rejected, rates = core.rejected_report(evidence, signals, actual_summary, config['cutoff'])
        reports.csv('live_actual_trade_costs.csv', actual)
        reports.csv('live_native_daily_financing.csv', financing)
        reports.json('live_actual_summary.json', actual_summary)
        reports.csv('live_rejected_paths.csv', rejected)
        reports.csv('resolved_actual_and_hypothetical_win_rates.csv', rates)
        reports.csv('live_broker_close_quotes.csv', broker_close_quotes(evidence, signals))
        reports.csv('watcher_health.csv', watcher_health(evidence, config['cutoff']))
        live = live_records(evidence, actual, config['cutoff'])
        # Broker trigger defaults are necessary for bid/ask comparisons on live protection.
        protection = []
        for item in live:
            try:
                obj = reader.get('broker', '/v3/accounts/' + config['account'] + '/trades/' + item['trade_key'])
                trade = obj.get('trade') or {}
                require(str(trade.get('id')) == item['trade_key'], 'Trade detail ID mismatch')
                for order_name in ('stopLossOrder', 'takeProfitOrder', 'trailingStopLossOrder'):
                    order = trade.get(order_name)
                    if order:
                        condition = order.get('triggerCondition', 'DEFAULT')
                        protection.append(dict(trade_id=item['trade_key'], order_type=order_name, state=order.get('state'),
                                               price=order.get('price'), trigger_condition=condition,
                                               default_exit_side_compatible=condition == 'DEFAULT'))
                        if condition != 'DEFAULT':
                            limits.append('Live trade ' + item['trade_key'] + ' has non-default ' + order_name + ' triggerCondition; candle default-side comparison is not its exact trigger rule.')
            except Exception as exc:
                protection.append(dict(trade_id=item['trade_key'], status='DETAIL_UNAVAILABLE', error=core.redact(str(exc), config)))
        reports.csv('live_protection_details.csv', protection)
        store = CandleStore(reader, config, directory)
        paths, traces, source_errors = [], {}, []
        book = reference['book'] if reference_override is None else reference_override['book']
        geometries = reference['geometry'] if reference_override is None else reference_override['geometry']
        require(len(book) == len(geometries), 'Internal test reference mismatch')
        long_indices = {i for i, r in enumerate(book) if (dt(r['exit']) - dt(r['entry'])).total_seconds() >= 168 * 3600}
        long_indices.update(sorted(range(len(book)), key=lambda i: dt(book[i]['exit']) - dt(book[i]['entry']), reverse=True)[:20])
        progress(phase='HISTORICAL_PRICE_PATHS', historical_required=len(book), historical_completed=0)
        with ThreadPoolExecutor(max_workers=config.get('workers', 4)) as pool:
            futures = {pool.submit(historical_trade, store, i, record, geometries[i]): i for i, record in enumerate(book)}
            for count, future in enumerate(as_completed(futures), 1):
                i = futures[future]
                try:
                    row, trace = future.result()
                    paths.append(row)
                    traces[i] = trace
                    reports.json('path_traces/' + str(i) + '.json', trace)
                    if i in long_indices:
                        native = store.range(book[i]['pair'], book[i]['tf'], dt(book[i]['entry']), dt(book[i]['exit']))
                        reports.csv('long_hold_native_paths/' + str(i) + '.csv', flatten_candles(native))
                except Exception as exc:
                    safe = core.redact(str(exc), config)
                    paths.append(dict(index=i, **book[i], archived_path_status='SOURCE_ERROR', error=safe))
                    source_errors.append(dict(stage='HISTORICAL_PATH', index=i, error=safe))
                progress(historical_completed=count, cache_downloads=store.downloads, cache_hits=store.hits)
        paths.sort(key=lambda r: r['index'])
        reports.csv('historical_path_summary.csv', paths)
        reports.csv('long_hold_path_review.csv', [r for r in paths if r['index'] in long_indices])
        jobs = []
        for i, record in enumerate(book):
            trace = traces.get(i, {})
            for boundary in core.boundaries(dt(record['entry']), dt(record['exit']), True):
                jobs.append(dict(cohort='HISTORICAL', trade_key=str(i), record=record, geometry=geometries[i], boundary=boundary,
                                 mid_touch=trace.get('mid_first_touch'), executable_touch=trace.get('executable_exit_first_touch')))
        funding_lookup = defaultdict(list)
        for row in financing:
            funding_lookup[(row['trade_id'], dt(row['time']).astimezone(NY).date())].append(row)
        for item in live:
            record, geometry = item['record'], item['geometry']
            for boundary in core.boundaries(dt(record['entry']), dt(record['exit']), True):
                allocation = funding_lookup.get((item['trade_key'], boundary.astimezone(NY).date()), [])
                cash = sum(row['financing_cash'] for row in allocation if row['financing_cash'] is not None) if allocation else None
                risk = item.get('cost_record', {}).get('risk_cash') if item.get('cost_record') else None
                jobs.append(dict(cohort='LIVE', trade_key=item['trade_key'], record=record, geometry=geometry,
                                 boundary=boundary, funding_cash=cash, funding_r=cash / risk if cash is not None and risk else None,
                                 source_cutoff_utc=stamp(config['cutoff'])))
        progress(phase='ROLLOVER_WINDOWS', rollover_required=len(jobs), rollover_completed=0)
        windows = []
        with ThreadPoolExecutor(max_workers=config.get('workers', 4)) as pool:
            futures = {pool.submit(rollover_event, store, job, schedules[job['record']['pair']]): job for job in jobs}
            for count, future in enumerate(as_completed(futures), 1):
                job = futures[future]
                try:
                    windows.append(future.result())
                except Exception as exc:
                    safe = core.redact(str(exc), config)
                    windows.append(dict(cohort=job['cohort'], trade_key=job['trade_key'], pair=job['record']['pair'],
                                        side=job['record']['side'], rollover_utc=stamp(job['boundary']), status='SOURCE_ERROR', error=safe))
                    source_errors.append(dict(stage='ROLLOVER_WINDOW', cohort=job['cohort'], trade_key=job['trade_key'],
                                              rollover_utc=stamp(job['boundary']), error=safe))
                progress(rollover_completed=count, cache_downloads=store.downloads, cache_hits=store.hits)
        windows.sort(key=lambda r: (r['cohort'], r.get('rollover_utc', ''), r['pair'], r['trade_key']))
        reports.csv('rollover_event_windows.csv', windows)
        reports.csv('rollover_summary_pair_side.csv', grouped_summary(windows))
        reports.csv('source_errors.csv', source_errors)
        mid_status = Counter(r['archived_path_status'] for r in paths)
        limits.extend([
            'Historical fills/stops for 2898 paths retain native-signal cost/stop models; winner R reconciles but -1R alone cannot independently validate loss geometry.',
            'Historical funding rates, holiday charging and true intrabar tick paths are unavailable. Current funding is an estimate; missing and ambiguous candle data remain unresolved.',
            'ASK/BID OPEN/CLOSE differences are candle-boundary spread proxies. Actual fullPrice observations are reported separately; no high-minus-low spread inference.',
            'The bid/ask path keeps frozen modeled entries and accepted admissions. It is not an executable all32 portfolio backtest or a replay of newly freed opportunities.',
            'Only five frozen raw signal streams are available; changing holding periods, entries or gates requires the remaining streams before portfolio policy admission.',
            'Historical archive overlaps the September live baseline and was repeatedly researched; it is not independent out-of-sample evidence.',
            'Recorded watcher snapshots may be later than the frozen live outcome cutoff and only cover their stated cycles.',
        ])
        if source_errors:
            limits.append(str(len(source_errors)) + ' source-read failures; inspect source_errors.csv before any whole-cohort conclusion.')
        summary = dict(status='COMPLETE_WITH_LIMITATIONS', version=VERSION, read_only=True, orders_sent=False,
                       live_trading_modified=False, baseline_controls_passed=len(controls),
                       historical_paths_attempted=len(paths), historical_expected=3391,
                       historical_mid_matches=mid_status['EXIT_KIND_AND_NATIVE_INTERVAL_MATCH'],
                       historical_mid_mismatches=mid_status['ARCHIVED_PATH_MISMATCH'],
                       historical_mid_unresolved=len(paths) - mid_status['EXIT_KIND_AND_NATIVE_INTERVAL_MATCH'] - mid_status['ARCHIVED_PATH_MISMATCH'],
                       historical_mid_status_counts=dict(mid_status), long_hold_paths=len(long_indices),
                       rollover_boundaries_attempted=len(windows), rollover_source_errors=sum(r['status'] == 'SOURCE_ERROR' for r in windows),
                       rollover_unexplained_gap_windows=sum(r.get('missing_unexplained_slots', 0) > 0 for r in windows),
                       cache_downloads=store.downloads, cache_hits=store.hits,
                       actual_live_summary=actual_summary, live_cutoff_utc=stamp(config['cutoff']),
                       finished_at_utc=stamp(datetime.now(UTC)), limitations=list(dict.fromkeys(limits)),
                       test_fixture=reference_override is not None)
        reports.json('RUN_COMPLETE.json', core.redact(summary, config))
        reports.text('READ_FIRST.md', review_text(summary))
        reports.json('request_receipts.json', core.redact(reader.receipts, config))
        progress(phase='PACKAGING_SOURCE_EVIDENCE')
        reports.save(directory, store)
        progress(status=summary['status'], phase='FINISHED', result='/results.zip',
                 historical_mid_matches=summary['historical_mid_matches'], historical_mid_mismatches=summary['historical_mid_mismatches'],
                 historical_mid_unresolved=summary['historical_mid_unresolved'], finished_at_utc=summary['finished_at_utc'])
        return summary
    except Exception as exc:
        safe = core.redact(str(exc), config or {})
        reports.json('ERROR.json', dict(status='ERROR', message=safe, read_only=True, orders_sent=False, version=VERSION))
        if reader:
            reports.json('request_receipts.json', core.redact(reader.receipts, config or {}))
        reports.save(directory, store)
        progress(status='ERROR', phase='FAILED', message=safe, result='/results.zip')
        raise
    finally:
        if store:
            store.close()


def start():
    with LOCK:
        if STATE['status'] != 'IDLE':
            return
        STATE.update(status='RUNNING', phase='STARTING')
    def worker():
        try:
            run_audit()
        except Exception:
            pass  # Redacted diagnostic ZIP and /status are persisted by run_audit.
    threading.Thread(target=worker, name='p32-read-only-rollover-audit', daemon=True).start()


def application(environ, start_response):
    method, path = environ.get('REQUEST_METHOD', 'GET'), environ.get('PATH_INFO', '/')
    if method not in ('GET', 'HEAD'):
        code, body, kind = '405 Method Not Allowed', b'GET/HEAD only', 'text/plain'
    elif path in ('/', '/health'):
        code, body, kind = '200 OK', canon(dict(service=VERSION, read_only=True, orders_supported=False,
                                               live_trading_modified=False, start_once='/status', download='/results.zip')), 'application/json'
    elif path == '/status':
        if method == 'GET':
            start()
        with LOCK:
            body = canon(dict(STATE))
        code, kind = '200 OK', 'application/json'
    elif path in ('/results', '/results.zip', '/download'):
        with LOCK:
            finished = STATE['status'] in ('COMPLETE_WITH_LIMITATIONS', 'ERROR')
        file = output_dir() / RESULT_NAME
        if finished and file.is_file():
            code, body, kind = '200 OK', file.read_bytes(), 'application/zip'
        else:
            code, body, kind = '409 Conflict', b'Not finished. Check /status.', 'text/plain'
    else:
        code, body, kind = '404 Not Found', b'Not found', 'text/plain'
    headers = [('Content-Type', kind), ('Content-Length', str(len(body))), ('Cache-Control', 'no-store')]
    if kind == 'application/zip':
        headers.append(('Content-Disposition', 'attachment; filename=' + RESULT_NAME))
    if code.startswith('405'):
        headers.append(('Allow', 'GET, HEAD'))
    start_response(code, headers)
    return [b'' if method == 'HEAD' else body]


class QuietHandler(WSGIRequestHandler):
    def log_message(self, format, *args):
        pass


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--run', action='store_true', help='Run once, then exit')
    parser.add_argument('--check-controls', action='store_true', help='Offline reference and six baseline controls')
    args = parser.parse_args()
    if args.check_controls:
        core = load_core()
        ref, payload, controls = load_reference(core)
        print(json.dumps(dict(status='PASS', baseline_controls=len(controls), historical_trades=len(ref['book']),
                              geometry=len(ref['geometry']), strategies=32, read_only=True), indent=2))
        return
    if args.run:
        try:
            print(json.dumps(run_audit(), indent=2))
        except Exception:
            raise SystemExit(1)
        return
    port = int(os.getenv('PORT', '8080'))
    with make_server('0.0.0.0', port, application, handler_class=QuietHandler) as server:
        print(VERSION + ' listening on PORT ' + str(port), flush=True)
        server.serve_forever()


